                q = deque([(r, c)])
                seen.add((r, c))
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
