def transform(grid):
    """Keep the solid rectangular color fields, removing sparse noise."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    colors = [v for v, n in counts.items() if v != bg and n >= 6]

    for color in colors:
        # Integral images make rectangle checks constant time.
        pref_color = [[0] * (w + 1) for _ in range(h + 1)]
        pref_bg = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                pref_color[r+1][c+1] = (pref_color[r][c+1] + pref_color[r+1][c]
                                         - pref_color[r][c] + (grid[r][c] == color))
                pref_bg[r+1][c+1] = (pref_bg[r][c+1] + pref_bg[r+1][c]
                                      - pref_bg[r][c] + (grid[r][c] == bg))

        def rect_sum(pref, r0, c0, r1, c1):
            return pref[r1+1][c1+1] - pref[r0][c1+1] - pref[r1+1][c0] + pref[r0][c0]

        boxes = []
        for r0 in range(h):
            for r1 in range(r0+1, h):
                height = r1-r0+1
                for c0 in range(w):
                    for c1 in range(c0+1, w):
                        area = height*(c1-c0+1)
                        if area < 4 or rect_sum(pref_bg,r0,c0,r1,c1):
                            continue
                        n = rect_sum(pref_color,r0,c0,r1,c1)
                        if n >= 3 and n/area >= 0.78:
                            boxes.append((r0,r1,c0,c1))
        for r0,r1,c0,c1 in boxes:
            if any(a <= r0 and b >= r1 and c <= c0 and d >= c1 and
                   (a < r0 or b > r1 or c < c0 or d > c1)
                   for a,b,c,d in boxes):
                continue
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    out[r][c] = color
    return out
